package com.secure.documentwallet;

import android.app.*;import android.content.*;import android.graphics.Color;import android.graphics.Typeface;import android.view.*;import android.widget.*;

/** Shared V8 Search Command Centre visual language used across every vault page. */
final class VaultPageUi {
 private VaultPageUi(){}
 static LinearLayout page(Activity a){LinearLayout p=Ui.column(a);p.setPadding(Ui.dp(a,14),Ui.dp(a,14),Ui.dp(a,14),Ui.dp(a,92));p.setBackgroundColor(Ui.BG);return p;}
 static ScrollView scroll(Activity a,LinearLayout page){ScrollView s=new ScrollView(a);s.setFillViewport(true);s.setClipToPadding(false);s.addView(page);return s;}
 static LinearLayout header(Activity a,String title,String subtitle){LinearLayout bar=new LinearLayout(a);bar.setGravity(Gravity.CENTER_VERTICAL);FrameLayout back=iconButtonView(a,"back","Back");back.setOnClickListener(v->a.finish());bar.addView(back,new LinearLayout.LayoutParams(Ui.dp(a,36),Ui.dp(a,36)));LinearLayout words=Ui.column(a);words.setPadding(Ui.dp(a,10),0,0,0);TextView heading=Ui.title(a,title,20);heading.setSingleLine(true);heading.setEllipsize(android.text.TextUtils.TruncateAt.END);words.addView(heading);if(subtitle!=null&&!subtitle.isEmpty()){TextView sub=Ui.text(a,subtitle,10,Ui.MUTED);sub.setPadding(0,Ui.dp(a,2),0,0);words.addView(sub);}bar.addView(words,new LinearLayout.LayoutParams(0,-2,1));LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,-2);bp.bottomMargin=Ui.dp(a,12);bar.setLayoutParams(bp);return bar;}
 static LinearLayout brandHeader(Activity a,String title,String subtitle){LinearLayout bar=new LinearLayout(a);bar.setGravity(Gravity.CENTER_VERTICAL);FrameLayout mark=iconWell(a,"vault",Color.WHITE,Ui.TEAL,12);bar.addView(mark,new LinearLayout.LayoutParams(Ui.dp(a,44),Ui.dp(a,44)));LinearLayout words=Ui.column(a);words.setPadding(Ui.dp(a,11),0,0,0);words.addView(Ui.title(a,title,26));TextView sub=Ui.text(a,subtitle,12,Ui.MUTED);sub.setPadding(0,Ui.dp(a,2),0,0);words.addView(sub);bar.addView(words,new LinearLayout.LayoutParams(0,-2,1));return bar;}
 static FrameLayout iconWell(Context c,String icon,int iconColor,int fill,int radius){FrameLayout well=new FrameLayout(c);well.setBackground(Ui.bg(fill,Ui.dp(c,radius)));VaultIconView glyph=new VaultIconView(c).setIcon(icon).setColor(iconColor);int pad=Ui.dp(c,9);well.setPadding(pad,pad,pad,pad);well.addView(glyph,new FrameLayout.LayoutParams(-1,-1));return well;}
 static FrameLayout iconButtonView(Context c,String icon,String description){FrameLayout b=iconWell(c,icon,Ui.INK,Ui.SURFACE,10);b.setBackground(Ui.stroke(Ui.SURFACE,Ui.dp(c,1),Ui.BORDER,Ui.dp(c,10)));b.setContentDescription(description);b.setElevation(Ui.dp(c,2));b.setClickable(true);b.setFocusable(true);return b;}
 static FrameLayout filterIcon(Context c,String icon,String description){FrameLayout b=iconWell(c,icon,Ui.TEAL,Ui.SOFT,11);b.setBackground(Ui.stroke(Ui.SOFT,Ui.dp(c,1),Ui.BORDER,Ui.dp(c,11)));b.setContentDescription(description);b.setElevation(Ui.dp(c,3));b.setClickable(true);b.setFocusable(true);return b;}
 static TextView iconButton(Context c,String symbol,String description){TextView b=Ui.text(c,symbol,21,Ui.INK);b.setGravity(Gravity.CENTER);b.setBackground(Ui.stroke(Ui.SURFACE,Ui.dp(c,1),Ui.BORDER,Ui.dp(c,13)));b.setContentDescription(description);b.setElevation(Ui.dp(c,2));return b;}
 static TextView section(Context c,String title){TextView t=Ui.title(c,title,17);t.setPadding(Ui.dp(c,2),Ui.dp(c,18),0,Ui.dp(c,8));return t;}
 static LinearLayout sectionHead(Context c,String title,String trailing){LinearLayout head=new LinearLayout(c);head.setGravity(Gravity.BOTTOM);TextView name=Ui.title(c,title,17);head.addView(name,new LinearLayout.LayoutParams(0,-2,1));if(trailing!=null){TextView note=Ui.text(c,trailing,11,Ui.MUTED);note.setGravity(Gravity.END);head.addView(note);}head.setPadding(Ui.dp(c,2),Ui.dp(c,18),Ui.dp(c,2),Ui.dp(c,8));return head;}
 static LinearLayout card(Context c){LinearLayout card=Ui.column(c);card.setPadding(Ui.dp(c,14),Ui.dp(c,13),Ui.dp(c,14),Ui.dp(c,13));card.setBackground(Ui.emissive(c,0,18));card.setElevation(Ui.dp(c,5));return card;}
 static LinearLayout row(Context c,String symbol,String title,String subtitle){LinearLayout row=new LinearLayout(c);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(Ui.dp(c,10),Ui.dp(c,9),Ui.dp(c,10),Ui.dp(c,9));row.setBackground(Ui.stroke(Ui.SURFACE,Ui.dp(c,1),Ui.BORDER,Ui.dp(c,15)));row.setElevation(Ui.dp(c,2));TextView icon=Ui.text(c,symbol,18,Ui.TEAL);icon.setGravity(Gravity.CENTER);icon.setBackground(Ui.bg(Ui.SOFT,Ui.dp(c,11)));row.addView(icon,new LinearLayout.LayoutParams(Ui.dp(c,42),Ui.dp(c,42)));LinearLayout words=Ui.column(c);words.setPadding(Ui.dp(c,11),0,Ui.dp(c,6),0);TextView name=Ui.title(c,title,14);name.setSingleLine(true);name.setEllipsize(android.text.TextUtils.TruncateAt.END);words.addView(name);if(subtitle!=null&&!subtitle.isEmpty()){TextView detail=Ui.text(c,subtitle,11,Ui.MUTED);detail.setSingleLine(true);detail.setEllipsize(android.text.TextUtils.TruncateAt.END);detail.setPadding(0,Ui.dp(c,3),0,0);words.addView(detail);}row.addView(words,new LinearLayout.LayoutParams(0,-2,1));TextView arrow=Ui.text(c,"›",23,Ui.MUTED);arrow.setGravity(Gravity.CENTER);row.addView(arrow,new LinearLayout.LayoutParams(Ui.dp(c,26),Ui.dp(c,42)));return row;}
 static LinearLayout iconRow(Context c,String iconName,String title,String subtitle){LinearLayout row=new LinearLayout(c);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(Ui.dp(c,9),Ui.dp(c,9),Ui.dp(c,9),Ui.dp(c,9));row.setBackground(Ui.emissive(c,1,13));row.setElevation(Ui.dp(c,4));FrameLayout icon=iconWell(c,iconName,Ui.TEAL,Ui.SOFT,10);row.addView(icon,new LinearLayout.LayoutParams(Ui.dp(c,40),Ui.dp(c,40)));LinearLayout words=Ui.column(c);words.setPadding(Ui.dp(c,10),0,Ui.dp(c,5),0);TextView name=Ui.title(c,title,13);name.setSingleLine(true);name.setEllipsize(android.text.TextUtils.TruncateAt.END);words.addView(name);if(subtitle!=null&&!subtitle.isEmpty()){TextView detail=Ui.text(c,subtitle,10,Ui.MUTED);detail.setSingleLine(true);detail.setEllipsize(android.text.TextUtils.TruncateAt.END);detail.setPadding(0,Ui.dp(c,2),0,0);words.addView(detail);}row.addView(words,new LinearLayout.LayoutParams(0,-2,1));TextView arrow=Ui.text(c,"›",20,Ui.MUTED);arrow.setGravity(Gravity.CENTER);row.addView(arrow,new LinearLayout.LayoutParams(Ui.dp(c,22),Ui.dp(c,40)));return row;}
 static void addRow(LinearLayout parent,View row){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=Ui.dp(parent.getContext(),8);parent.addView(row,p);}
 static TextView primary(Context c,String label){TextView button=Ui.text(c,label,14,Color.WHITE);button.setGravity(Gravity.CENTER);button.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));button.setBackground(Ui.bg(Ui.TEAL,Ui.dp(c,13)));button.setElevation(Ui.dp(c,3));return button;}
 static TextView secondary(Context c,String label){TextView button=Ui.text(c,label,13,Ui.INK);button.setGravity(Gravity.CENTER);button.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));button.setBackground(Ui.stroke(Ui.SURFACE,Ui.dp(c,1),Ui.BORDER,Ui.dp(c,14)));return button;}
 static void button(LinearLayout parent,View button){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,Ui.dp(parent.getContext(),48));p.topMargin=Ui.dp(parent.getContext(),9);parent.addView(button,p);}
 static LinearLayout notice(Context c,String symbol,String title,String text,int fill,int accent){LinearLayout box=card(c);box.setBackground(Ui.stroke(fill,Ui.dp(c,1),Ui.BORDER,Ui.dp(c,17)));LinearLayout top=new LinearLayout(c);top.setGravity(Gravity.CENTER_VERTICAL);TextView mark=Ui.text(c,symbol,18,accent);mark.setGravity(Gravity.CENTER);mark.setBackground(Ui.bg(Ui.SURFACE,Ui.dp(c,10)));top.addView(mark,new LinearLayout.LayoutParams(Ui.dp(c,38),Ui.dp(c,38)));LinearLayout copy=Ui.column(c);copy.setPadding(Ui.dp(c,10),0,0,0);copy.addView(Ui.title(c,title,14));copy.addView(Ui.text(c,text,10,Ui.MUTED));top.addView(copy,new LinearLayout.LayoutParams(0,-2,1));box.addView(top);return box;}
 static LinearLayout toggleRow(Context c,String symbol,String title,String detail,boolean checked,android.widget.CompoundButton.OnCheckedChangeListener listener){LinearLayout row=new LinearLayout(c);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(0,Ui.dp(c,7),0,Ui.dp(c,7));TextView icon=Ui.text(c,symbol,17,Ui.TEAL);icon.setGravity(Gravity.CENTER);icon.setBackground(Ui.bg(Ui.SOFT,Ui.dp(c,11)));row.addView(icon,new LinearLayout.LayoutParams(Ui.dp(c,40),Ui.dp(c,40)));LinearLayout words=Ui.column(c);words.setPadding(Ui.dp(c,10),0,0,0);words.addView(Ui.title(c,title,13));words.addView(Ui.text(c,detail,10,Ui.MUTED));row.addView(words,new LinearLayout.LayoutParams(0,-2,1));Switch sw=new Switch(c);sw.setChecked(checked);if(listener!=null)sw.setOnCheckedChangeListener(listener);row.addView(sw);return row;}
 static TextView badge(Context c,String label){TextView badge=Ui.text(c,label.toUpperCase(),9,0xff168365);badge.setGravity(Gravity.CENTER);badge.setTypeface(null,Typeface.BOLD);badge.setBackground(Ui.bg(0xffe4f6ef,Ui.dp(c,20)));badge.setPadding(Ui.dp(c,9),0,Ui.dp(c,9),0);return badge;}
 static FrameLayout screen(Activity a,LinearLayout page,String active){FrameLayout root=new FrameLayout(a);root.setBackgroundColor(Ui.BG);root.addView(scroll(a,page),new FrameLayout.LayoutParams(-1,-1));LinearLayout nav=bottomNav(a,active);FrameLayout.LayoutParams np=new FrameLayout.LayoutParams(-1,Ui.dp(a,62),Gravity.BOTTOM);np.setMargins(Ui.dp(a,10),0,Ui.dp(a,10),Ui.dp(a,10));root.addView(nav,np);return root;}
 static LinearLayout bottomNav(Activity a,String active){LinearLayout nav=new LinearLayout(a);nav.setGravity(Gravity.CENTER);nav.setPadding(Ui.dp(a,5),Ui.dp(a,4),Ui.dp(a,5),Ui.dp(a,4));nav.setBackground(Ui.emissive(a,2,18));nav.setElevation(Ui.dp(a,14));nav.addView(navItem(a,"home","Home","home".equals(active),v->go(a,MainActivity.class)),new LinearLayout.LayoutParams(0,-1,1));nav.addView(navItem(a,"folder","Vault","vault".equals(active),v->go(a,VaultSearchActivity.class)),new LinearLayout.LayoutParams(0,-1,1));FrameLayout scan=iconWell(a,"scan",Color.WHITE,Ui.TEAL,14);scan.setElevation(Ui.dp(a,8));scan.setContentDescription("Scan");scan.setOnClickListener(v->{if(a instanceof MainActivity)((MainActivity)a).openQuickScan();else go(a,MainActivity.class);});LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(Ui.dp(a,50),Ui.dp(a,50));sp.setMargins(Ui.dp(a,4),-Ui.dp(a,8),Ui.dp(a,4),0);nav.addView(scan,sp);nav.addView(navItem(a,"clock","Recent","recent".equals(active),v->go(a,VaultActivityTimelineActivity.class)),new LinearLayout.LayoutParams(0,-1,1));nav.addView(navItem(a,"user","Profile","profile".equals(active),v->go(a,VaultSettingsActivity.class)),new LinearLayout.LayoutParams(0,-1,1));return nav;}
 private static LinearLayout navItem(Activity a,String icon,String label,boolean active,View.OnClickListener click){LinearLayout item=Ui.column(a);item.setGravity(Gravity.CENTER);VaultIconView symbol=new VaultIconView(a).setIcon(icon).setColor(active?Ui.TEAL:Ui.MUTED);item.addView(symbol,new LinearLayout.LayoutParams(Ui.dp(a,21),Ui.dp(a,21)));TextView text=Ui.text(a,label,9,active?Ui.TEAL:Ui.MUTED);text.setGravity(Gravity.CENTER);item.addView(text);item.setOnClickListener(click);return item;}
 private static void go(Activity a,Class<? extends Activity> type){if(a.getClass()==type)return;a.startActivity(new Intent(a,type));}
}
